# Population Stability Index + two-sample Kolmogorov-Smirnov.
# Pure standard library on purpose: this node runs under Pyodide, which cannot
# reliably import scipy or numpy. Verified to match scipy.stats.ks_2samp.
import math

def _quantile(xs, q):
    if not xs:
        return 0.0
    pos = q * (len(xs) - 1)
    lo = int(math.floor(pos))
    hi = min(lo + 1, len(xs) - 1)
    return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo)

def psi(expected, actual, buckets=10, eps=1e-6):
    if not expected or not actual:
        return 0.0
    ref = sorted(expected)
    edges = [_quantile(ref, i / buckets) for i in range(1, buckets)]

    def bucketize(xs):
        counts = [0] * buckets
        for x in xs:
            idx = 0
            while idx < len(edges) and x > edges[idx]:
                idx += 1
            counts[idx] += 1
        return [c / len(xs) for c in counts]

    e, a = bucketize(ref), bucketize(actual)
    return sum((ai - ei) * math.log((ai + eps) / (ei + eps)) for ei, ai in zip(e, a))

def ks_2samp(a, b):
    if not a or not b:
        return 0.0, 1.0
    xa, xb = sorted(a), sorted(b)
    n, m = len(xa), len(xb)
    i = j = 0
    d = 0.0
    while i < n and j < m:
        if xa[i] <= xb[j]:
            i += 1
        else:
            j += 1
        d = max(d, abs(i / n - j / m))
    en = math.sqrt(n * m / (n + m))
    lam = (en + 0.12 + 0.11 / en) * d
    p = 2.0 * sum((-1) ** (k - 1) * math.exp(-2.0 * k * k * lam * lam) for k in range(1, 101))
    return d, max(0.0, min(1.0, p))

# Pyodide hands JavaScript objects across as proxies; normalise defensively.
raw = _input.first().json
try:
    data = raw.to_py()
except AttributeError:
    data = dict(raw)

reference = [float(x) for x in data["reference"]]
live = [float(x) for x in data["live"]]

score = psi(reference, live)
d, p = ks_2samp(reference, live)

return [{
    "json": {
        "model_name": data["model_name"],
        "psi": round(score, 4),
        "ks_statistic": round(d, 4),
        "p_value": p,
        "drifted_features": [data["feature"]] if score > 0.2 else [],
        "window_start": data["window_start"],
        "window_end": data["window_end"],
        "n_samples": len(live),
        "severity": "high" if score > 0.25 else ("moderate" if score > 0.1 else "stable"),
    }
}]
